@ApiOperation("投保")
    @PostMapping("/underwrite")
    public GenericRpcResponse<OrderInfoVO> underwrite(@RequestBody OrderUnderwriteReq req) {
        log.info("提交核保入参: req=[{}]", JSON.toJSONString(req));
        return requestProcess(() -> {
            SessionContext.User user = SessionContext.obtain().getUser();
            //user和sharedId不能同时为空
            if (StringUtils.isBlank(user.getUserId()) && StringUtils.isBlank(req.getSharedId())) {
                throw new WechatBizException(WechatErrorCodeEnum.WECHAT_BIZ_ILLEGAL_UNDERWRITING);
            }
            //校验验证码
            if (isBlank(req.getVerifyCode())) {
                throw new WechatBizException(WechatErrorCodeEnum.WECHAT_BIZ_VERIFY_CODE_ERROR);
            }
            boolean result = shortMessageVerificationService.verifyLogin(req.getProposalInfo().getCustomerInfo().getHolder().getContactTelephone(), req.getVerifyCode(), ShortMessageType.DEFAULT, LocalDateTime.now());
            if (!result) {
                throw new WechatBizException(WechatErrorCodeEnum.WECHAT_BIZ_VERIFY_CODE_ERROR);
            }
            //保单生效日期判断
            if (nonNull(req.getProposalInfo()) && isNotEmpty(req.getProposalInfo().getExtendInfo())&&isNotBlank(req.getProposalInfo().getExtendInfo().get(EFFECTIVE_DATE))){
                LocalDate effectiveDate= DateUtils.localDate(req.getProposalInfo().getExtendInfo().get(EFFECTIVE_DATE));
                //保单生效日不在可选范围内
                if(isNull(effectiveDate)||effectiveDate.isBefore(LocalDate.now().plusDays(3))||effectiveDate.isAfter(LocalDate.now().plusDays(30))){
                    throw new WechatBizException(WECHAT_BIZ_1035);
                }
            }
            return proposalService.underwriting(req, user.getUserId());
        }, "提交核保");

    }

@SuppressWarnings("unchecked")
    protected <T> GatewayResponse<T> requestProcess(Supplier<T> processor, String serviceDesc) {
        try {
            return GatewayResponse.success(processor.get());
        } catch (AgreementException e) {
            log.warn(serviceDesc + "-{}", errorMessage(e.getErrorCode(), e.getErrorMsg()), e);
            //前端异常提示信息转换
            return GatewayResponse.fail( e.getErrorMsg());
        }catch (EclipseRuntimeException e){
            log.error(serviceDesc + "-{}",e.getMessage());
            //前端异常提示信息转换
            return GatewayResponse.fail(AgreementErrorEnum.BIZ_ERROR.getMsg());
        } catch ( Throwable e) {
            log.error(serviceDesc + "-未知异常捕获-{}", e.getMessage(), e);
            return GatewayResponse.fail(AgreementErrorEnum.SYSTEM_ERROR.getMsg());
        }
    }

@SuppressWarnings("unchecked")
    protected <T> GenericRpcResponse<T> requestProcess(Supplier<T> processor, String serviceLog) {
        try {
            return GenericRpcResponse.success(processor.get());
        } catch (EclipseRuntimeException e) {
            log.error(serviceLog + " 处理异常", e);
            throw new EclipseRuntimeException(e.getMessage(), e.getCode());
        } catch (Exception e) {
            log.error(serviceLog + " 处理异常", e);
            throw new EclipseRuntimeException(ErrorCodeEnum.SYSTEM_ERROR, e.getMessage());
        }
    }

protected <T> GenericRpcResponse<T> requestProcess(Supplier<T> processor, String serviceDesc) {
        try {
            return GenericRpcResponse.success(processor.get());
        } catch (ContinueDutyBizException e) {
            log.error(serviceDesc + "-{}", errorMessage(e.getErrorCode(), e.getErrorMsg()), e);
            return GenericRpcResponse.fail(null, e.getErrorMsg());
        } catch (Exception e) {
            log.error(serviceDesc + "-未知异常捕获-{}", e.getMessage(), e);
            return GenericRpcResponse.fail(null, ContinueDutyErrorCodeEnum.SYSTEM_ERROR.getMsg());
        }
    }

@SuppressWarnings("unchecked")
    protected <T> GenericRpcResponse<T> requestProcess(Supplier<T> processor, String serviceDesc) {
        try {
            return GenericRpcResponse.success(processor.get());
        }catch (EclipseException eclipseException){
            RpcError rpcError = new RpcError(eclipseException.getErrorEnum().getErrorCode(), Arrays.stream(eclipseException.getArgs()).map(String::valueOf).collect(Collectors.toList()).get(0));
            return GenericRpcResponse.fail(Lists.newArrayList(rpcError), rpcError.getErrorMessage());
        } catch (WechatBaseException e) {
            log.error(serviceDesc + "-{}", errorMessage(e.getErrorCode(), e.getErrorMsg()), e);
            //前端异常提示信息转换
            return GenericRpcResponse.fail(null, WechatErrorCodeEnum.transfer(WechatErrorCodeEnum.getByCode(e.getErrorCode())).getMsg());
        } catch (Exception e) {
            log.error(serviceDesc + "-未知异常捕获-{}", e.getMessage(), e);
            return GenericRpcResponse.fail(null, WechatErrorCodeEnum.SYSTEM_ERROR.getMsg());
        }
    }

@Test
    public void requestProcess() {
        GenericRpcResponse<String> response = controller.requestProcess(() -> {
            return "结果";
        }, "测试服务");
        assertNotNull(response.getData());
    }

@Override
    public EndorseMessage updateStatus(String trafficEndorseNo, String businessEndorseNo, boolean isSuccess, String errorMsg) {
        /**
         * 批单号会重复使用，有可能查询出来多条记录
         */
        List<EndorseMessage> endorseMessages = endorseMessageRepository.findByEndorseNo(trafficEndorseNo, businessEndorseNo);
        if (isEmpty(endorseMessages)) {
            return null;
        }
        EndorseMessage endorseMessage = endorseMessages.get(0);
        /**
         * 取第一条，如果没有更新记录，则更新记录
         */
        if (nonNull(endorseMessage) && isNull(endorseMessage.getIsSuccess())) {
            endorseMessage.setMsg(errorMsg);
            endorseMessage.setIsSuccess(isSuccess);
            endorseMessage.setTemplateId(templateId);
            endorseMessage.lastModified("system", LocalDateTime.now());
            endorseMessageRepository.save(endorseMessage);
            return endorseMessage;
        }
        return null;
    }

